test_that("simulation validation is strict", {x<-bench_fixture();expect_invisible(validate_sblrbench_simulation(x));y<-x;y$truth$effects<-y$truth$effects[-1,,drop=FALSE];expect_error(validate_sblrbench_simulation(y),"dimensions");y<-x;y$data$marker_ids[2]<-y$data$marker_ids[1];expect_error(validate_sblrbench_simulation(y),"unique");y<-x;y$data$sample_ids[2]<-y$data$sample_ids[1];expect_error(validate_sblrbench_simulation(y),"unique");y<-x;y$data$train_ids<-"bad";expect_error(validate_sblrbench_simulation(y),"subset");y<-x;y$data$train_ids<-"s1";y$data$test_ids<-"s1";expect_error(validate_sblrbench_simulation(y),"overlap")})
test_that("mtsim converts and genotype retention is optional", {skip_if_not_installed("sblr");W<-matrix(sample(0:2,80,TRUE),10,8,dimnames=list(paste0("i",1:10),paste0("r",1:8)));raw<-sblr::mtsim(W=W,nt=2,n_shared=1,n_specific=1,seed=2);x<-as_sblrbench_simulation(raw);expect_identical(x$data$marker_ids,colnames(raw$W));expect_identical(x$data$sample_ids,rownames(raw$W));expect_identical(x$data$trait_names,colnames(raw$B));expect_null(as_sblrbench_simulation(raw,keep_genotypes=FALSE)$data$genotypes);expect_equal(as_sblrbench_simulation(raw,keep_genotypes=FALSE)$truth$effects,raw$B)})
